import{_ as t,o as a,c as n,a3 as r}from"./chunks/framework.DQ-7HQaQ.js";const u=JSON.parse('{"title":"Harvest plan for a clean build","description":"","frontmatter":{},"headers":[],"relativePath":"reuse/harvest-plan.md","filePath":"reuse/harvest-plan.md","lastUpdated":1794374806000}'),o={name:"reuse/harvest-plan.md"};function i(s,e,d,c,l,p){return a(),n("div",null,[...e[0]||(e[0]=[r(`<h1 id="harvest-plan-for-a-clean-build" tabindex="-1">Harvest plan for a clean build <a class="header-anchor" href="#harvest-plan-for-a-clean-build" aria-label="Permalink to &quot;Harvest plan for a clean build&quot;">​</a></h1><p><strong>Goal:</strong> preserve tested behaviors from Ordo while creating a small, comprehensible research system. This is a plan for subsequent implementation, not a claim that the application already builds.</p><h2 id="extraction-order" tabindex="-1">Extraction order <a class="header-anchor" href="#extraction-order" aria-label="Permalink to &quot;Extraction order&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Slice</th><th>Donor</th><th>New boundary</th><th>Keep out</th></tr></thead><tbody><tr><td>1. Contracts</td><td>Current executor/projection types; historical event types</td><td><code>contracts/</code> schemas and Rust domain types</td><td>UI framework objects, business persona text, arbitrary JSON authority</td></tr><tr><td>2. Durable kernel</td><td>H-01 <code>kernel.rs</code>; H-02 <code>events.rs</code></td><td><code>lab-store</code> and <code>lab-workflows</code></td><td>Process-local event files; global public replay; unfenced completion</td></tr><tr><td>3. Evidence review</td><td>H-03 graph candidate and promotion concepts</td><td><code>lab-knowledge</code> commands inside store transactions</td><td>Hash-derived canonical identities; automatic endpoint approval; one confidence number for everything</td></tr><tr><td>4. Processing</td><td>Owner-reviewed executor steps</td><td><code>lab-worker</code> capability implementations</td><td>Private research inputs, absolute user paths, generic public shell execution</td></tr><tr><td>5. Conversation</td><td>C-01 gateway; W-01 stream consumer behavior</td><td><code>lab-api</code>, model adapters and Svelte UI</td><td>Client-supplied permissions, silent fallback, transport-coupled domain state</td></tr><tr><td>6. Operations</td><td>Hosting studio/release patterns</td><td>Immutable release and isolated QA</td><td>Blind server reinstall, shared production secrets, builds on the live host</td></tr></tbody></table><p>See <a href="./source-audit">source audit</a> for exact code and <a href="./../project/roadmap">roadmap</a> for dependencies.</p><h2 id="a-bounded-extraction-procedure" tabindex="-1">A bounded extraction procedure <a class="header-anchor" href="#a-bounded-extraction-procedure" aria-label="Permalink to &quot;A bounded extraction procedure&quot;">​</a></h2><p>For each candidate, record the source commit, blob, path, symbol, license and intended behavior. Read the function&#39;s callers, schema migrations and tests before extracting it. The audit above is a starting map, not a complete transitive dependency analysis.</p><p>Create a donor characterization test around the behavior that matters. Then reproduce that behavior against a small target interface and add the missing negative tests. Keep the donor test result separate from the target result. A failing donor test is evidence to investigate, not an instruction to weaken the test.</p><p>Transfer one behavior per issue/PR. Preserve attribution and notices where source is copied. When the boundary needs a fresh implementation, document which donor behavior it preserves and which assumptions it deliberately changes. Do not call this a legal clean-room process; it is an evidence-based engineering rebuild informed by existing code.</p><h2 id="proposed-rust-dependency-direction" tabindex="-1">Proposed Rust dependency direction <a class="header-anchor" href="#proposed-rust-dependency-direction" aria-label="Permalink to &quot;Proposed Rust dependency direction&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>lab-domain       IDs, states, qualifiers, policy decisions; no HTTP or SQLite</span></span>
<span class="line"><span>lab-contracts    versioned wire schemas and validation</span></span>
<span class="line"><span>lab-store        SQLite transactions, artifacts, migrations and export</span></span>
<span class="line"><span>lab-workflows    DAG planning and state transitions through store commands</span></span>
<span class="line"><span>lab-knowledge    identity, claims, review and retrieval planning</span></span>
<span class="line"><span>lab-api          authorization, HTTP/SSE and conversation orchestration</span></span>
<span class="line"><span>lab-worker       capability execution; no direct canonical-table access</span></span></code></pre></div><p>These are proposed modules, not a requirement to create seven deployable services. Start with a Cargo workspace; share domain libraries rather than copy them between binaries. The hosted profile separates the stateless API from the stateful backing store. Local authoring may embed the store explicitly. The <a href="./../engineering/twelve-factor">twelve-factor page</a> defines the difference.</p><h2 id="example-move-the-historical-job-kernel" tabindex="-1">Example: move the historical job kernel <a class="header-anchor" href="#example-move-the-historical-job-kernel" aria-label="Permalink to &quot;Example: move the historical job kernel&quot;">​</a></h2><p><code>create_job_from_template_with_idempotency</code> currently depends on capability registration, template variables, compiled plans, diagnostics and events. Extract those as explicit inputs and narrow collaborators, not by copying the entire daemon.</p><p>The target command should receive an authenticated actor scope, a versioned plan, normalized inputs and a request key. Its store transaction must reject changed inputs for an existing key, insert job/tasks/dependencies, and append the creation events together. External inference and filesystem decoding happen outside that transaction.</p><p>The target result-acceptance command receives a lease receipt containing job/task, worker, epoch and expiry, plus the input digest and output manifest. It validates artifact bytes and scope before a conditional acceptance update. Lease checks must occur in the same transaction as acceptance; checking a lease in memory and writing later creates a race.</p><h2 id="example-replace-candidate-ids-without-losing-provenance" tabindex="-1">Example: replace candidate IDs without losing provenance <a class="header-anchor" href="#example-replace-candidate-ids-without-losing-provenance" aria-label="Permalink to &quot;Example: replace candidate IDs without losing provenance&quot;">​</a></h2><p>Retain the old candidate ID and origin as import provenance. Assign stable canonical entity IDs independently. Mention-to-entity decisions are versioned records. A change in source wording, evidence count or extraction model creates a new proposal or derivation, not automatically a new entity.</p><p>For edges, distinguish a qualified proposition from each source&#39;s assertion about it. A repeated source import may be deduplicated; independent testimony must remain independent. Aliases are scoped many-to-many lookup records, not global uniqueness keys.</p><h2 id="admission-checklist-for-every-transferred-module" tabindex="-1">Admission checklist for every transferred module <a class="header-anchor" href="#admission-checklist-for-every-transferred-module" aria-label="Permalink to &quot;Admission checklist for every transferred module&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Check</th><th>Required evidence</th></tr></thead><tbody><tr><td>Rights and exposure</td><td>Source pin, applicable notices, approved public/private disposition</td></tr><tr><td>Dependency control</td><td>Minimal crate/API dependencies; declared external tools and model manifests</td></tr><tr><td>Behavioral compatibility</td><td>Characterization fixtures plus documented intentional differences</td></tr><tr><td>Fault handling</td><td>Cancellation, bounded inputs, corruption, retries and recovery tests</td></tr><tr><td>Persistence</td><td>One transaction owner; no hidden writes in presentation or worker code</td></tr><tr><td>Documentation</td><td>Requirement, donor symbol, target module, issue and actual test receipt linked</td></tr></tbody></table><p>No task closes because an AI says the implementation looks correct. It closes when the scoped acceptance evidence is present. Application PRs need their own review; this documentation PR does not authorize importing the whole Ordo product.</p>`,22)])])}const m=t(o,[["render",i]]);export{u as __pageData,m as default};
